package com.tripmateai.entity;
import com.tripmateai.enums.ExpenseStatus; import jakarta.persistence.*; import jakarta.validation.constraints.*; import lombok.*; import java.math.BigDecimal; import java.time.LocalDate;
@Entity @Table(name="expenses",indexes={@Index(name="idx_expenses_trip_date",columnList="trip_id,expense_date"),@Index(name="idx_expenses_user",columnList="user_id")}) @Getter @Setter @NoArgsConstructor @EqualsAndHashCode(callSuper=true,onlyExplicitlyIncluded=true) @ToString
public class Expense extends BaseEntity { @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="trip_id",nullable=false) @ToString.Exclude private Trip trip; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="user_id",nullable=false) @ToString.Exclude private User user; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="category_id") @ToString.Exclude private ExpenseCategory category; @NotBlank @Size(max=200) @Column(nullable=false,length=200) private String title; @DecimalMin("0.00") @Column(nullable=false,precision=12,scale=2) private BigDecimal amount; @Column(name="expense_date",nullable=false) private LocalDate expenseDate; @Enumerated(EnumType.STRING) @Column(nullable=false,length=20) private ExpenseStatus status=ExpenseStatus.PENDING; @Size(max=2048) @Column(name="receipt_url",length=2048) private String receiptUrl; }
